openclash:
table inet fw4 {
	chain openclash { # handle 687
		ip daddr @localnetwork counter packets 2205 bytes 115680 return # handle 688
		ct direction reply counter packets 0 bytes 0 return # handle 689
		ip protocol tcp ip daddr 198.18.0.0/16 counter packets 0 bytes 0 redirect to :7892 # handle 690
		ip protocol tcp counter packets 28491 bytes 1620354 redirect to :7892 # handle 691
	}
}
table inet fw4 {
	chain mangle_output { # handle 28
		type route hook output priority mangle; policy accept;
	}
}

cake_service:
#!/bin/sh /etc/rc.common
START=96
STOP=10
USE_PROCD=1

start_service() {
    procd_open_instance
    procd_set_param command /usr/libexec/codex-cake watch
    procd_set_param respawn 3600 5 5
    procd_close_instance
}

stop_service() {
    /usr/libexec/codex-cake stop
}
